{
  "findings": [
    {
      "check_id": "CKV_AZURE_114",
      "title": "Key Vault secret content type is not set",
      "resource": "azurerm_key_vault_secret.database_connection_string",
      "severity": "MEDIUM",
      "explanation": "The Key Vault secret does not define content_type, reducing metadata clarity and making it harder for consumers and operators to identify and handle the connection string appropriately."
    }
  ],
  "patched_code": "resource \"azurerm_key_vault_secret\" \"database_connection_string\" {\n  name         = \"database-connection-string\"\n  value        = \"Server=tcp:${azurerm_mssql_server.legal_sql_server.fully_qualified_domain_name},1433;Database=${azurerm_mssql_database.legal_metadata_db.name};User ID=${var.sql_admin_username};Password=${var.sql_admin_password};Encrypt=true;TrustServerCertificate=false;Connection Timeout=30;\"\n  key_vault_id = azurerm_key_vault.legal_keyvault.id\n  content_type = \"application/x-sql-connection-string\"\n  depends_on   = [azurerm_mssql_database.legal_metadata_db]\n}\n",
  "fix_summary": "Added an explicit content_type identifying the secret as a SQL connection string."
}
